// Queue<T> defines the interface to a queue collection.
public interface Queue<T> {
  // enqueue adds one element of type T to the rear of this queue.
  void enqueue(T element);
  // dequeue removes and returns the element at the front of this queue.
  T dequeue();
  // first returns the front element without removing it.
  T first();
  // isEmpty returns true if this queue is empty, and false otherwise.
  boolean isEmpty();
  // size returns the number of elements in this queue.
  int size();
  // toString returns a string representation of this queue.
  String toString();
}

