public T dequeue() throws RuntimeException {
  if (count == 0) throw new RuntimeException("Queue is empty\n");
  T element = front.element;
                                      // Reference to front element
  Node<T> next = front.next;
                                      // Reference to next node
  front.next = null;
                                      // Disconnect front node from list
  front = next;
                                      // front now references next node
  count--;
                                      // Decrement the count of elements
  if (count == 0) rear = null;
                                      // If queue becomes empty
  return element;
                                      // Reference to removed element
}

